function safeConfig(url,key){
 const u=new URL(url);
 if(u.protocol!=='https:'||!/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/.test(u.href))throw Error('Use a staging Supabase HTTPS project URL.');
 if(u.hostname!=='kakpnafzcnvvnhmrwecd.supabase.co')throw Error('Only the isolated Racing Hub staging project is permitted.');
 if(!key||key.length<20)throw Error('Enter a valid publishable key.');
 if(key.startsWith('sb_secret_')||key.startsWith('eyJ')&&key.includes('service_role'))throw Error('Never enter a secret/service-role key.');
 return {url:u.origin,key};
}
async function refreshSession(){
 if(!refreshToken)throw Error('Session expired. Please sign in again.');
 const response=await fetch(cfg.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:cfg.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:refreshToken})});
 if(!response.ok)throw Error('Session expired. Please sign in again.');
 const data=await response.json();token=data.access_token;refreshToken=data.refresh_token;expiresAt=Date.now()+Math.max(0,(data.expires_in||3600)-60)*1000;
}
async function request(path,{method='GET',body}={}){
 if(Date.now()>=expiresAt)await refreshSession();
 const response=await fetch(cfg.url+'/rest/v1/'+path,{method,headers:{apikey:cfg.key,...(token?{Authorization:'Bearer '+token}:{}),...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});
 if(!response.ok)throw Error('Database request failed ('+response.status+').');
 if(response.status===204||response.status===201&&response.headers.get('content-length')==='0')return null;
 const raw=await response.text();return raw?JSON.parse(raw):null;
}
async function importV22(body){if(Date.now()>=expiresAt)await refreshSession();const r=await fetch(cfg.url+'/functions/v1/racing-v22-import',{method:'POST',headers:{apikey:cfg.key,Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||'Historical import failed');return data;}
