async function login(email,password){
 const r=await fetch(cfg.url+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:cfg.key,'Content-Type':'application/json'},body:JSON.stringify({email,password})});
 if(!r.ok){const failure=await r.json().catch(()=>({}));const code=failure.error_code||failure.code||'';if(code==='email_not_confirmed')throw Error('Email not confirmed. Check your inbox and junk folder, or use Resend confirmation email.');if(code==='invalid_credentials')throw Error('Incorrect email or password. Check your staging sign-in details.');if(r.status===429)throw Error('Too many sign-in attempts. Please wait before trying again.');throw Error('Sign-in failed ('+r.status+'). '+(typeof failure.msg==='string'?failure.msg:'Please try again.'));}
 const data=await r.json();token=data.access_token;authUser=data.user?.id;
 refreshToken=data.refresh_token;expiresAt=Date.now()+Math.max(0,(data.expires_in||3600)-60)*1000;
 if(!token||!authUser||!refreshToken)throw Error('Missing session identity');
}
