 const owned=allTeams.filter(t=>t.status==='active');const recovery=$('team-recovery');recovery.replaceChildren();for(const t of allTeams.filter(t=>t.status==='archived'&&t.owner_user_id===authUser)){const row=record(t.name,'Archived '+new Date(t.archived_at).toLocaleDateString());const b=document.createElement('button');b.textContent='Restore';b.disabled=!t.archived_at||Date.now()-Date.parse(t.archived_at)>30*86400000;b.addEventListener('click',async()=>{try{await lifecycle('restore',t.id);await loadTeams();message('Team restored.');}catch(e){message(e.message);}});row.append(b);recovery.append(row);}if(!recovery.childNodes.length)recovery.textContent='No archived teams.';
