function exportResultsCsv(items,names,events,adjustments){const cell=v=>{const raw=String(v??'');const safe=typeof v==='string'&&/^[=+@-]/.test(raw)?"'"+raw:raw;return '"'+safe.replaceAll('"','""')+'"';};const header=['Race','Racer','Finish','Grid','Final points','Fastest lap','DNF','Race time','Time penalty','Points adjustment','Event ID','Racer ID'];const lines=[header.map(cell).join(',')];for(const r of items){const penalty=adjustments.get(r.event_id+'|'+r.racer_id)||0;const row=[events.get(r.event_id)||'Race',names.get(r.racer_id)||'Racer',r.finishing_position??'',r.grid_position??'',Math.max(0,(Number(r.points)||0)+penalty),r.fastest_lap?'Yes':'No',r.dnf?'Yes':'No',r.race_time||'',r.time_penalty||'',penalty,r.event_id,r.racer_id];lines.push(row.map(cell).join(','));}const blob=new Blob([String.fromCharCode(0xFEFF)+lines.join(String.fromCharCode(13,10))],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fenz-racing-results-'+teamId.slice(0,8)+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function exportRacingData(){if(!ownerTeamIds.has(teamId))throw Error('Team owner permission required');const selectedTeam=teamId;const tablesToExport=['team_events','race_results','team_racers','team_announcements','team_rules','team_championships','championship_events','team_trophies','team_achievements','team_tracks','team_cars','team_leagues','team_race_rsvps','team_event_rosters'];const data={format:'fenz-racing-hub-team-export-v1',team_id:selectedTeam,exported_at:new Date().toISOString(),scope:'racing-records-only',records:{}};for(const table of tablesToExport){const rows=[];for(let offset=0;offset<100000;offset+=1000){const page=await request(table+'?select=*&team_id=eq.'+encodeURIComponent(selectedTeam)+'&limit=1000&offset='+offset);if(!Array.isArray(page))throw Error('Unexpected response while exporting '+table);rows.push(...page);if(page.length<1000)break;if(offset===99000)throw Error('Export row limit reached');}data.records[table]=rows;}if(teamId!==selectedTeam)throw Error('Team changed during export');const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='fenz-racing-team-'+selectedTeam.slice(0,8)+'-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);message('Racing data export prepared. This is not a full migration backup.');}
