$('legacy-import-form').addEventListener('submit',async e=>{e.preventDefault();try{if(!ownerTeamIds.has(teamId))throw Error('Owner permission required');const file=$('legacy-import-file').files?.[0];if(!file||file.size>2000000)throw Error('Select a V22.6 JSON backup under 2 MB');const backup=JSON.parse(await file.text());const audit=validateLegacyExport(backup);if(!audit.ok)throw Error('Backup validation failed: '+audit.errors.slice(0,3).join('; '));const selected=teamId,name=teamInfo.get(selected)?.name||selected;if(!confirm('Import the verified V22.6 history into EMPTY STAGING team '+name+'? This does not affect production.'))return;$('legacy-import-submit').disabled=true;message('Importing and reconciling historical records...');const result=await importV22({team_id:selected,backup});if(teamId===selected){await loadImportStatus();await loadDashboard();}message('Mi5 V22.6 history imported into staging. '+(result.normalized?.results||0)+' results preserved.');}catch(err){message(err.message);if(ownerTeamIds.has(teamId))await loadImportStatus().catch(()=>{});}});
