$('scoring-form').addEventListener('submit',async e=>{e.preventDefault();try{if(!canScore())throw Error('Scoring permission required');const event_id=$('score-event').value.trim(),racer_id=$('score-racer').value.trim();if(!uuid.test(event_id)||!uuid.test(racer_id))throw Error('Valid race and racer UUIDs required');const dnf=$('score-dnf').checked,finishing_position=dnf?null:Number($('score-position').value),grid_position=$('score-grid').value?Number($('score-grid').value):null,fastest_lap=$('score-fastest').checked,penalty_points=Number($('score-penalty').value||0),race_time=$('score-time').value.trim(),points=Number($('score-points').value);if((!dnf&&(!Number.isInteger(finishing_position)||finishing_position<1))||(grid_position!==null&&(!Number.isInteger(grid_position)||grid_position<1))||!Number.isFinite(points)||points<0||!Number.isFinite(penalty_points)||(dnf&&points!==0))throw Error('Invalid race result. DNF must score zero points.');const editId=$('scoring-form').dataset.editId;await request(editId?'race_results?id=eq.'+encodeURIComponent(editId)+'&team_id=eq.'+teamId:'race_results',{method:editId?'PATCH':'POST',body:editId?{event_id,racer_id,finishing_position,points,grid_position,fastest_lap,dnf,penalty_points,race_time}:{team_id:teamId,event_id,racer_id,finishing_position,points,grid_position,fastest_lap,dnf,penalty_points,race_time}});delete $('scoring-form').dataset.editId;$('scoring-form').reset();await loadDashboard();message('Race result saved to staging.');}catch(err){message(err.message);}});
